B.aw6=new A.fH("Tribunal de proximit\xe9","Juridiction qui traite les litiges inf\xe9rieurs \xe0 10 000 euros. Proc\xe9dure simplifi\xe9e, avocat non obligatoire.",null,"Recours",2)
